#!/bin/bash
# T0 (minutes): unit tests (t0_units.txt), popiii_regress.jl (snapshots regenerated by phase6_run.jl pure), noh_test.jl. Sourced by gate.sh.
# Everything runs in a SANDBOX copy of julia/ under $OUT/t0 (TitanFortran creates lib/ dirs, the tdc tests write logs under docs/): the worktree stays clean.

t0_unit() {   # name script args envwords donere timeout cores
  local name=$1 script=$2 args=$3 envw=$4 donere=$5 to=$6 cores=$7 D=$OUT/t0 rc npass nfail done_=0
  ( cd $D/sandbox/julia && env $envw ${GATE_T0_ENV:-} timeout $to numactl --physcpubind=$cores --localalloc julia -t $GATE_THREADS --project=$JLENV $script $args > $D/$name.out 2>&1 < /dev/null ); rc=$?
  npass=$(grep -cE '^\s*(PASS|ok)\b' $D/$name.out); nfail=$(grep -cE '(^|\s)FAIL(\s|$|:)' $D/$name.out)
  [ -z "$donere" ] || grep -qE "$donere" $D/$name.out && done_=1
  [ -z "$donere" ] && done_=1
  { kv $D/$name.kv t0.$name.pass $npass; kv $D/$name.kv t0.$name.fail $nfail; kv $D/$name.kv t0.$name.exit $rc; kv $D/$name.kv t0.$name.done $done_
    local bad=0; { [ $rc -ne 0 ] || [ $nfail -ne 0 ] || [ $done_ -ne 1 ]; } && bad=1; kv $D/$name.kv t0.$name.failed $bad; }
}

tier_t0() {
  local D=$OUT/t0; rm -rf $D; mkdir -p $D; : > $D/notes.txt
  # sandbox: copy of julia/ (without bulky outputs), links to the data the scripts read
  mkdir -p $D/sandbox/lib; cp -r $WT/julia $D/sandbox/julia; ln -s $WT/reference_runs $D/sandbox/reference_runs; ln -s $WT/fortran $D/sandbox/fortran
  [ -d $WT/lib/src ] && ln -s $WT/lib/src $D/sandbox/lib/src
  pool_init $D
  local l
  while IFS= read -r l; do
    l=${l%%#*}; [ -n "${l// /}" ] || continue
    IFS='|' read -r name script args envw donere to <<< "$l"
    name=$(echo $name); script=$(echo $script); to=$(echo $to)
    pool_launch t0_unit "$name" "$script" "$(echo $args)" "$(echo $envw)" "$(echo $donere)" "$to"
  done < $PROTO/t0_units.txt
  pool_wait
  # ---- popiii_regress.jl: its inputs lib/p2_runs/<NAME>_pure/snaps.jls are produced by `phase6_run.jl pure NAME` from reference_runs/init/NAME.tstate.gz
  local cores=${SLOTS[0]} reg_ok=1 n
  for n in SOD SUBC SUPC; do
    [ -f $WT/reference_runs/init/$n.tstate.gz ] || { reg_ok=0; echo "SKIP popiii_regress: reference_runs/init/$n.tstate.gz missing (the Fortran capture of phase6_run.jl is not run here)" >> $D/notes.txt; }
  done
  if [ $reg_ok = 1 ]; then
    for n in SOD SUBC SUPC; do
      ( cd $D/sandbox/julia && env TITAN_NOLIB=1 $([ $n = SOD ] && echo TITAN_SET=jstepe=3000) timeout ${GATE_REG_TIMEOUT:-1800} numactl --physcpubind=$cores --localalloc julia -t $GATE_THREADS --project=$JLENV phase6_run.jl pure $n > $D/phase6_$n.out 2>&1 < /dev/null ) \
        || { reg_ok=0; echo "SKIP popiii_regress: phase6_run.jl pure $n failed (see t0/phase6_$n.out): $(tail -1 $D/phase6_$n.out | cut -c1-160)" >> $D/notes.txt; }
    done
  fi
  if [ $reg_ok = 1 ]; then
    ( cd $D/sandbox/julia && TITAN_NOLIB=1 timeout 900 numactl --physcpubind=$cores --localalloc julia -t $GATE_THREADS --project=$JLENV popiii_regress.jl > $D/popiii_regress.out 2>&1 < /dev/null ); local rc=$?
    local nf; nf=$(grep -c 'FAIL' $D/popiii_regress.out)
    kv $D/regress.kv t0.regress.exit $rc; kv $D/regress.kv t0.regress.fail $nf; kv $D/regress.kv t0.regress.accept $(grep -c '^ACCEPT' $D/popiii_regress.out)
    kv $D/regress.kv t0.regress.failed $([ $rc -ne 0 ] || [ $nf -ne 0 ] && echo 1 || echo 0); kv $D/regress.kv t0.regress.fail_lines $nf
  else kv $D/regress.kv t0.regress.skipped 1; fi
  # ---- noh_test.jl needs TitanFortran with TITAN_NOLIB=1 (state in Julia arrays); SKIP if it cannot initialise
  ( cd $D/sandbox/julia && TITAN_NOLIB=1 timeout ${GATE_NOH_TIMEOUT:-1800} numactl --physcpubind=$cores --localalloc julia -t $GATE_THREADS --project=$JLENV noh_test.jl ${GATE_NOH_N:-100} > $D/noh_test.out 2>&1 < /dev/null ); local rn=$?
  if [ $rn -eq 124 ]; then
    echo "SKIP noh_test: no result within ${GATE_NOH_TIMEOUT:-1800} s (timeout; the box is loaded or n is too large: GATE_NOH_N, GATE_NOH_TIMEOUT); it initialised and was stepping" >> $D/notes.txt; kv $D/noh.kv t0.noh.skipped 1
  elif [ $rn -ne 0 ] && grep -qE "libtitan|TitanFortran|dlopen|could not load|not loadable|Fortran" $D/noh_test.out && ! grep -q "^Noh n=" $D/noh_test.out; then
    echo "SKIP noh_test: cannot initialise ($(grep -m1 -E 'ERROR|Error' $D/noh_test.out | cut -c1-200))" >> $D/notes.txt; kv $D/noh.kv t0.noh.skipped 1
  elif [ $rn -ne 0 ]; then kv $D/noh.kv t0.noh.failed 1; kv $D/noh.kv t0.noh.exit $rn
  else   # the printed shock-radius ratio and plateau medians against the exact solution
    kv $D/noh.kv t0.noh.failed 0; kv $D/noh.kv t0.noh.exit 0
    sed -nE 's/^shock radius .*ratio ([0-9.]+)$/t0.noh.shock_ratio \1/p' $D/noh_test.out >> $D/noh.kv
    sed -nE 's/^plateau .*T\/T_RH median ([0-9.]+) min [0-9.]+ max [0-9.]+; .*rho\/\(64.0\) median ([0-9.]+).*/t0.noh.T_over_TRH \1\nt0.noh.rho_over_64rho0 \2/p' $D/noh_test.out >> $D/noh.kv
  fi
  python3 - $D <<'PY'
import glob, sys
d = sys.argv[1]; tot = 0; ex = 0; n = 0; fl = 0
for f in glob.glob(d + "/*.kv"):
    for ln in open(f):
        k, v = ln.split(); v = float(v)
        if 'regress' in k: continue     # popiii_regress is judged against the reference run (tol.json), not absolutely
        if k.endswith(".fail") and k.startswith("t0."): tot += v
        if k.endswith(".exit") and v != 0: ex += 1
        if k.endswith(".failed") and v: fl += 1
open(d + "/total.kv", "w").write("t0.fail_lines_total %d\nt0.exit_nonzero_total %d\nt0.units_failed %d\n" % (tot, ex, fl))
PY
  python3 $PROTO/finalize.py $D T0
}
